<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #11182b;
      --panel-2: #17203a;
      --text: #f4f7fb;
      --muted: #a9b4cc;
      --border: #2a3656;
      --accent: #7c8cff;
      --accent-strong: #9aa6ff;
      --danger: #ff7272;
      --danger-strong: #ff9595;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      min-height: 100%;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #182448 0%, transparent 36%),
        linear-gradient(180deg, #0a1020 0%, #070b16 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #0c1120;
      transform: translateY(-200%);
      transition: transform 180ms ease;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4.5rem 1.25rem 2rem;
    }

    .preview-shell {
      width: min(100%, 42rem);
      padding: 1.25rem;
    }

    h1 {
      margin: 0 0 1rem;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .subtle {
      margin: 0 0 1.5rem;
      max-width: 36rem;
      color: var(--muted);
      line-height: 1.6;
    }

    .card {
      border: 1px solid color-mix(in srgb, var(--border) 78%, white 22%);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, rgba(23, 32, 58, 0.96), rgba(13, 19, 36, 0.98));
      box-shadow: var(--shadow);
      overflow: clip;
    }

    .media {
      padding: 1rem;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent 45%),
        var(--panel);
    }

    .media img {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      border-radius: 1rem;
      border: 1px solid var(--border);
      background: #0c1120;
    }

    .meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.1rem 1.15rem;
    }

    .caption {
      min-width: 0;
    }

    .caption strong,
    .caption span {
      display: block;
    }

    .caption strong {
      font-size: 1.05rem;
      margin-bottom: 0.2rem;
    }

    .caption span {
      color: var(--muted);
      font-size: 0.96rem;
      line-height: 1.5;
    }

    .trigger {
      border: 1px solid color-mix(in srgb, var(--danger) 65%, white 35%);
      background: linear-gradient(180deg, color-mix(in srgb, var(--danger) 24%, #24121b 76%), #1b1020);
      color: var(--text);
      border-radius: 999px;
      padding: 0.8rem 1.15rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 10px 24px rgba(0, 0, 0, 0.18);
      transition: transform 160ms ease, border-color 160ms ease, background-color 160ms ease;
    }

    .trigger:hover {
      transform: translateY(-1px);
      border-color: var(--danger-strong);
    }

    .trigger:focus-visible,
    .dialog-actions button:focus-visible {
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    .trigger:active {
      transform: translateY(0);
    }

    .status {
      margin: 1rem 0 0;
      min-height: 1.5rem;
      color: var(--muted);
    }

    dialog {
      width: min(100% - 2rem, 32rem);
      border: 1px solid color-mix(in srgb, var(--border) 72%, white 28%);
      border-radius: 1.5rem;
      padding: 0;
      background: linear-gradient(180deg, #151d33 0%, #0e1425 100%);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 14, 0.74);
      backdrop-filter: blur(10px);
    }

    .dialog-card {
      margin: 0;
      padding: 1.35rem;
    }

    .dialog-kicker {
      margin: 0 0 0.55rem;
      color: var(--danger-strong);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .dialog-title {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -0.03em;
    }

    .dialog-body {
      margin: 0.8rem 0 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.4rem;
    }

    .dialog-actions button {
      border-radius: 999px;
      padding: 0.8rem 1.1rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 160ms ease, border-color 160ms ease, background-color 160ms ease;
    }

    .dialog-actions .secondary {
      border: 1px solid var(--border);
      background: #121a31;
      color: var(--text);
    }

    .dialog-actions .secondary:hover {
      border-color: #41507d;
      transform: translateY(-1px);
    }

    .dialog-actions .danger {
      border: 1px solid color-mix(in srgb, var(--danger) 68%, white 32%);
      background: linear-gradient(180deg, color-mix(in srgb, var(--danger) 34%, #431821 66%), #2c1218);
      color: var(--text);
    }

    .dialog-actions .danger:hover {
      border-color: var(--danger-strong);
      transform: translateY(-1px);
    }

    @media (max-width: 540px) {
      .meta {
        flex-direction: column;
        align-items: stretch;
      }

      .trigger {
        width: 100%;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-actions button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .card,
      .trigger,
      dialog,
      .dialog-actions button,
      .media img {
        forced-color-adjust: auto;
        border-color: ButtonBorder;
        background: Canvas;
        color: CanvasText;
      }

      dialog::backdrop {
        background: Canvas;
      }

      .trigger:focus-visible,
      .dialog-actions button:focus-visible {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="preview-shell" aria-labelledby="page-title">
      <h1 id="page-title">Image preview</h1>
      <p class="subtle">Review the image before deciding whether to keep it in your library.</p>

      <div class="card" id="preview-card">
        <div class="media">
          <img
            src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80"
            alt="A desk with a laptop, notebook, and warm lamp light"
          >
        </div>
        <div class="meta">
          <div class="caption">
            <strong>Desk setup</strong>
            <span>Added to your library today</span>
          </div>
          <button class="trigger" type="button" id="delete-trigger">
            Delete image
          </button>
        </div>
      </div>

      <p class="status" id="status" aria-live="polite" tabindex="-1"></p>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
    <form method="dialog" class="dialog-card">
      <p class="dialog-kicker">Confirm deletion</p>
      <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
      <p class="dialog-body" id="delete-desc">
        This will remove the image from your library. This action cannot be undone.
      </p>

      <div class="dialog-actions">
        <button class="secondary" value="cancel">Cancel</button>
        <button class="danger" value="delete">Delete</button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('delete-trigger');
    const previewCard = document.getElementById('preview-card');
    const status = document.getElementById('status');

    let lastTrigger = trigger;

    trigger.addEventListener('click', () => {
      lastTrigger = document.activeElement === trigger ? trigger : lastTrigger;
      dialog.showModal();
      dialog.querySelector('.secondary').focus();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue === 'delete') {
        previewCard.hidden = true;
        status.textContent = 'The image was deleted from your library.';
        status.focus();
        return;
      }

      lastTrigger.focus();
    });
  </script>
</body>
</html>
