 <body>
   <a class="skip-link" href="#main">Skip to main content</a>

   <main id="main">
     <section class="preview-shell" aria-labelledby="page-title">
       <h1 id="page-title">Image preview</h1>
       <p class="subtle">Review the image before deciding whether to keep it in your library.</p>

       <div class="card" id="preview-card">
         <div class="media">
           <img
             src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80"
             alt="A desk with a laptop, notebook, and warm lamp light"
           >
         </div>
         <div class="meta">
           <div class="caption">
             <strong>Desk setup</strong>
             <span>Added to your library today</span>
           </div>
           <button class="trigger" type="button" id="delete-trigger">
             Delete image
           </button>
         </div>
       </div>

       <p class="status" id="status" aria-live="polite" tabindex="-1"></p>
     </section>
   </main>

   <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
     <form method="dialog" class="dialog-card">
       <p class="dialog-kicker">Confirm deletion</p>
       <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
       <p class="dialog-body" id="delete-desc">
         This will remove the image from your library. This action cannot be undone.
       </p>

       <div class="dialog-actions">
         <button class="secondary" value="cancel">Cancel</button>
         <button class="danger" value="delete">Delete</button>
       </div>
     </form>
   </dialog>

   <script>
     const dialog = document.getElementById('delete-dialog');
     const trigger = document.getElementById('delete-trigger');
     const previewCard = document.getElementById('preview-card');
     const status = document.getElementById('status');

     let lastTrigger = trigger;

     trigger.addEventListener('click', () => {
       lastTrigger = document.activeElement === trigger ? trigger : lastTrigger;
       dialog.showModal();
       dialog.querySelector('.secondary').focus();
     });

     dialog.addEventListener('close', () => {
       if (dialog.returnValue === 'delete') {
         previewCard.hidden = true;
         status.textContent = 'The image was deleted from your library.';
         status.focus();
         return;
       }

       lastTrigger.focus();
     });
   </script>
